+void ShutdownEvent::accept() {
+    accepted_ = true;
+    rejected_ = false;
+    reason_.clear();
+}
+
+void ShutdownEvent::reject(const QString& reason) {
+    rejected_ = true;
+    accepted_ = false;
+    reason_ = reason;
+}
+
+bool ShutdownEvent::isAccepted() const {
+    return accepted_ && !rejected_;
+}
+
+QString ShutdownEvent::reason() const {
+    return reason_;
+}
