-static char *get_appcast_update_url(software_update_channel_e chan, const char* su_application, const char* su_version) {
-    GString *update_url_str = g_string_new("");
-    const char *chan_name;
-
-    switch (chan) {
-        case UPDATE_CHANNEL_DEVELOPMENT:
-            chan_name = "development";
-            break;
-        default:
-            chan_name = "stable";
-            break;
-    }
-    g_string_printf(update_url_str, "https://www.wireshark.org/%s/%u/%s/%s/%s/%s/en-US/%s.xml",
-                    SU_SCHEMA_PREFIX,
-                    SU_SCHEMA_VERSION,
-                    su_application,
-                    su_version,
-                    SU_OSNAME,
-                    SU_ARCH,
-                    chan_name);
-    return g_string_free(update_url_str, FALSE);
-}
